//go:build linux

package syscallx

import "golang.org/x/sys/unix"

func Get() (Info, error) {
	var si unix.Sysinfo_t
	if err := unix.Sysinfo(&si); err != nil {
		return Info{}, err
	}

	unit := uint64(si.Unit)
	if unit == 0 {
		unit = 1
	}

	info := Info{
		UptimeSeconds: uint64(si.Uptime),
		TotalMemory:   si.Totalram * unit,
		FreeMemory:    si.Freeram * unit,
	}

	if la, err := unix.Getloadavg(); err == nil {
		info.Load1 = la[0]
	}

	return info, nil
}

//go:build darwin

package syscallx

import (
	"unsafe"

	"golang.org/x/sys/unix"
)

func Get() (Info, error) {
	raw, err := unix.SysctlRaw("kern.boottime")
	if err != nil {
		return Info{}, err
	}
	if len(raw) < int(unsafe.Sizeof(unix.Timeval{})) {
		return Info{}, unix.EINVAL
	}

	boot := *(*unix.Timeval)(unsafe.Pointer(&raw[0]))
	info := Info{UptimeSeconds: uint64(unix.TimevalToTime(boot).Unix())}

	if total, err := unix.SysctlUint64("hw.memsize"); err == nil {
		info.TotalMemory = total
	}
	if pageSize, err := unix.SysctlUint32("hw.pagesize"); err == nil {
		if freePages, err := unix.SysctlUint32("vm.page_free_count"); err == nil {
			info.FreeMemory = uint64(pageSize) * uint64(freePages)
		}
	}
	if la, err := unix.Getloadavg(); err == nil {
		info.Load1 = la[0]
	}

	return info, nil
}

//go:build windows

package syscallx

import (
	"unsafe"

	"golang.org/x/sys/windows"
)

func Get() (Info, error) {
	var mem windows.MemoryStatusEx
	mem.Length = uint32(unsafe.Sizeof(mem))
	if err := windows.GlobalMemoryStatusEx(&mem); err != nil {
		return Info{}, err
	}

	return Info{
		UptimeSeconds: windows.GetTickCount64() / 1000,
		TotalMemory:   mem.TotalPhys,
		FreeMemory:    mem.AvailPhys,
	}, nil
}

package main

import (
	"fmt"
	"os"

	"example.com/syscallcli/internal/syscallx"
)

func main() {
	info, err := syscallx.Get()
	if err != nil {
		fmt.Fprintln(os.Stderr, "syscallcli:", err)
		os.Exit(1)
	}

	fmt.Printf("uptime:       %ds\n", info.UptimeSeconds)
	fmt.Printf("total memory: %d bytes\n", info.TotalMemory)
	fmt.Printf("free memory:  %d bytes\n", info.FreeMemory)
	if info.Load1 > 0 {
		fmt.Printf("load (1m):    %.2f\n", info.Load1)
	}
}

